// The question, the solver's reference facts, and the criteria the judge scores against.
return [{ json: {
  "task": "Screen the bundled workshop_co2_298K_synthetic and workshop_n2_298K_synthetic datasets for CO2/N2 separation at 15% CO2 and 1 bar.",
  "reference": "Facts computed by LASP's solver for this question:\n- CO2 is best fitted by dsl. For N2, toth, quad, langmuir fit about equally well.\n- IAST selectivity at 1 bar and 15% CO2, by N2 model: toth 414, quad 420, langmuir 388.\n- IAST needs the N2 isotherm at about 59 bar; N2 was fitted only up to 10 bar.",
  "criteria": {
    "selectivity": "Gives a selectivity within the reference values and says which isotherm models it used.",
    "extrapolation": "Says IAST uses the N2 isotherm far beyond its fitted range, so the result is uncertain.",
    "tied models": "Notes that several N2 models fit about equally well, and compares their selectivities or justifies the one it chose."
  }
} }];

// One item per criterion, each carrying the agent's answer, so the judge scores them one at a time.
const setup = $('Question and criteria').first().json;
const answer = $('AI Agent').first().json.output;
return Object.entries(setup.criteria).map(([name, criterion]) =>
  ({ json: { name, criterion, answer, reference: setup.reference } }));

// Read each verdict (tolerating text around the JSON) and build the scorecard.
const criteria = $('One item per criterion').all().map(i => i.json.name);
const rows = $input.all().map((item, i) => {
  const text = String(item.json.text ?? '');
  let score = 0, reason = 'unreadable verdict: ' + text.slice(0, 80);
  try {
    const v = JSON.parse(text.match(/\{[\s\S]*\}/)[0]);
    score = Math.min(1, Math.max(0, Number(v.score) || 0));
    reason = v.reason || '';
  } catch (e) {}
  return { criterion: criteria[i], score, reason };
});
const average = rows.reduce((a, r) => a + r.score, 0) / rows.length;
return [{ json: { average: Math.round(100 * average) / 100, rows } }];
